55	public class DettaglioComunicazioneRenderCommand implements MVCRenderCommand {
56		
57		private static final Log log = LogFactoryUtil.getLog(DettaglioComunicazioneRenderCommand.class);
58		public static final String ROLE_CITTADINO = "Cittadino";
59		
60		public static final int MESSAGGI_MAX = 5;
61	
62		@Reference
63		private ComunicazioneLocalService comunicazioneLocalService;
64		
65		@Reference
66		private MessaggioLocalService messaggioLocalService;
67		
68		@Reference
69		private OrganizationUtility organizationUtility;
70	
71		@Reference
72		private CommentoDomandaBandoLocalService commentoDomandaBandoLocalService;
73	
74		@Reference
75		private CommentoRichiestaLocalService commentoRichiestaLocalService;
76		
77		@Reference
78		private UserLocalService userLocalService;
79		
80		@Reference
81		private RoleLocalService roleLocalService;
82		
83		@Reference
84		private LetturaMessaggioLocalService letturaMessaggioLocalService;
85		
86		@Reference
87		private ScrivaniaCittadinoMiddlewareService scrivaniaCittadinoMiddlewareService;
88		
89		@Override
90		public String render(RenderRequest renderRequest, RenderResponse renderResponse) throws PortletException {
91			int cur = ParamUtil.getInteger(renderRequest, "cur", 1);
92			int delta = ParamUtil.getInteger(renderRequest, "delta", 5);
93			long comunicazioneId = ParamUtil.getLong(renderRequest, ScrivaniaCittadinoPortletKeys.PARAM_COMUNICAZIONE_ID);
94			String tipologiaComunicazioneString = ParamUtil.getString(renderRequest, ScrivaniaCittadinoPortletKeys.PARAM_TIPOLOGIA_COMUNICAZIONE);
95			TipologiaComunicazione tipologiaComunicazione = TipologiaComunicazione.getByKey(tipologiaComunicazioneString);
96	
97			ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);
98	
99			int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
100			int start = limits[0];
101			int end = limits[1];
102	
103			ComunicazioneDto dto = getDettaglioComunicazione(comunicazioneId, 
104					tipologiaComunicazione, 
105					start, end, 
106					themeDisplay.getCompanyId(), 
107					themeDisplay.getScopeGroupId(), 
108					themeDisplay.getSiteDefaultLocale(),
109					themeDisplay.getUserId());
110	
111			renderRequest.setAttribute("comunicazione", dto);
112			
113			switch (tipologiaComunicazione){
114				case COMUNICAZIONE:
115					if (dto.getSubOrganizationId() > 0) {
116		        		long[] organizationIds = userLocalService.getOrganizationUserIds(dto.getSubOrganizationId());
117		        		letturaMessaggioLocalService.setMessaggiLetti(comunicazioneId, themeDisplay.getUserId(), organizationIds);
118					} else {
119						letturaMessaggioLocalService.setMessaggiLetti(comunicazioneId, themeDisplay.getUserId());
120					}
121					break;
122				case COMMENTO_DOMANDA_BANDO:
123					scrivaniaCittadinoMiddlewareService.setLetturaCommentoDomandaBando(comunicazioneId);
124					break;
125				case COMMENTO_RICHIESTA_SERVIZIO:
126					scrivaniaCittadinoMiddlewareService.setLetturaCommentoRichiesta(comunicazioneId);
127					break;
128				default:
129					throw new PortletException("TipologiaComunicazione non definita");
130		}
131			
132			
133			return "/comunicazione.jsp";
134		}
135	
136		private ComunicazioneDto getDettaglioComunicazione(long comunicazioneId, TipologiaComunicazione tipologiaComunicazione, int start, int end, long companyId, long scoupeGroupId, Locale locale, long userId) throws PortletException {
137			MessageUtility messageUtility = new MessageUtility(ScrivaniaCittadinoPortletKeys.BUNDLE_SYMBOLIC_NAME, locale);
138	
139			ComunicazioneDto dto = null;
140	
141			if(comunicazioneId > 0 && tipologiaComunicazione != null){
142				try{
143					switch (tipologiaComunicazione){
144						case COMUNICAZIONE:
145							dto = getComunicazione(comunicazioneId, start, end, companyId, scoupeGroupId, userId);
146							break;
147						case COMMENTO_DOMANDA_BANDO:
148							dto = getCommentoDomandaBando(comunicazioneId, messageUtility);
149							break;
150						case COMMENTO_RICHIESTA_SERVIZIO:
151							dto = getCommentoRichiesta(comunicazioneId, messageUtility);
152							break;
153						default:
154							throw new PortletException("TipologiaComunicazione non definita");
155					}
156	
157					hideBackOfficeName(dto,companyId, scoupeGroupId);
158	
159				}catch(PortalException portalException){
160					throw new PortletException(portalException);
161				}
162			}
163	
164			return dto;
165		}
166	
167		private ComunicazioneDto getComunicazione(long comunicazioneId, int start, int end, long companyId, long scoupeGroupId, long userId) throws PortletException {
168			ComunicazioneDto comunicazioneDto = null;
169			try {
170				Comunicazione comunicazione = comunicazioneLocalService.getComunicazione(comunicazioneId);
171	
172				if(comunicazione != null){
173					comunicazioneDto = mapComunicazione(comunicazione, start, end, companyId, scoupeGroupId, userId);
174				}
175			} catch (PortalException e) {
176				throw new PortletException(e);
177			}
178	
179			return comunicazioneDto;
180		}
181	
182		private ComunicazioneDto getCommentoDomandaBando(long commentoId, MessageUtility messageUtility) throws PortletException {
183			ComunicazioneDto commentoDto = null;
184	
185			try {
186				CommentoDomandaBando commentoDomandaBando = commentoDomandaBandoLocalService.getCommentoDomandaBando(commentoId);
187				if(commentoDomandaBando != null){
188					commentoDto = new ComunicazioneDto();
189					commentoDto.setCreateDate(commentoDomandaBando.getCreateDate());
190					commentoDto.setDomandaBandoId(commentoDomandaBando.getDomandaBandoId());
191	
192					commentoDto.setTitolo(messageUtility.getMessage("titolo-comunicazione-domanda-bando", commentoDomandaBando.getDomandaBandoId()));
193					MessaggioDTO messaggioDTO = new MessaggioDTO();
194					messaggioDTO.setContenuto(commentoDomandaBando.getTesto());
195					messaggioDTO.setUserId(commentoDomandaBando.getUserId());
196					commentoDto.setMessaggi(Collections.singletonList(messaggioDTO));
197	
198					commentoDto.setTipologia(TipologiaComunicazione.COMMENTO_DOMANDA_BANDO.getKey());
199				}
200			} catch (PortalException e) {
201				throw new PortletException(e);
202			}
203	
204			return commentoDto;
205		}
206	
207		private ComunicazioneDto getCommentoRichiesta(long commentoId, MessageUtility messageUtility) throws PortletException {
208			ComunicazioneDto commentoDto = null;
209	
210			try {
211				CommentoRichiesta commentoDomandaBando = commentoRichiestaLocalService.getCommentoRichiesta(commentoId);
212				if(commentoDomandaBando != null){
213					commentoDto = new ComunicazioneDto();
214					commentoDto.setCreateDate(commentoDomandaBando.getCreateDate());
215					commentoDto.setRichiestaId(commentoDomandaBando.getRichiestaId());
216	
217					commentoDto.setTitolo(messageUtility.getMessage("titolo-comunicazione-richiesta-servizio", commentoDomandaBando.getRichiestaId()));
218					MessaggioDTO messaggioDTO = new MessaggioDTO();
219					messaggioDTO.setContenuto(commentoDomandaBando.getTesto());
220					messaggioDTO.setUserId(commentoDomandaBando.getUserId());
221					commentoDto.setMessaggi(Collections.singletonList(messaggioDTO));
222	
223					commentoDto.setTitolo(commentoDomandaBando.getTesto());
224					commentoDto.setTipologia(TipologiaComunicazione.COMMENTO_RICHIESTA_SERVIZIO.getKey());
225				}
226			} catch (PortalException e) {
227				throw new PortletException(e);
228			}
229	
230			return commentoDto;
231		}
232	
233		private ComunicazioneDto mapComunicazione(Comunicazione comunicazione, int start, int end, long companyId, long scoupeGroupId, long userId) {
234			List<Messaggio> messaggi = messaggioLocalService.getMessaggi(comunicazione.getComunicazioneId(), start, end);
235	
236			ComunicazioneDto dto = new ComunicazioneDto();
237			dto.setId(comunicazione.getComunicazioneId());
238			dto.setNumMess(messaggioLocalService.countMessaggi(comunicazione.getComunicazioneId()));
239			
240			List<MessaggioDTO> messaggiDto = new ArrayList<MessaggioDTO>();
241			int size = 0;
242			do {
243				
244				messaggi = messaggioLocalService.getMessaggi(comunicazione.getComunicazioneId(), start + size, end + size);
245				messaggiDto.addAll(messaggi.stream()
246						.filter(messaggio -> filterMessaggio(messaggio, companyId, userId))
247						.map(this::mapMessaggio)
248						.collect(Collectors.toList()));
249				
250				size = messaggiDto.size() + 1;
251			}while(size < MESSAGGI_MAX && !messaggi.isEmpty());
252			
253			
254			dto.setMessaggi(messaggiDto);
255			dto.setRichiestaId(comunicazione.getRichiestaId());
256			dto.setDomandaBandoId(comunicazione.getDomandaBandoId());
257			dto.setTipologia(TipologiaComunicazione.COMUNICAZIONE.getKey());
258			dto.setSoloLettura(comunicazione.getReply());
259			
260			if(companyId > 0 && scoupeGroupId > 0) {
261				try {
262					hideBackOfficeName(dto, companyId, scoupeGroupId);
263				} catch (Exception e) {
264					log.error("errore in aggiornamento nomi back office", e);
265					throw new RuntimeException(e);
266				}
267			}
268			dto.setSubOrganizationId(comunicazione.getSubOrganizationId());
269			return dto;
270		}
271	
272		private boolean filterMessaggio(Messaggio messaggio, long companyId, long loggedUserId) {
273			long userId = messaggio.getUserId();
274			
275			if (userId == loggedUserId || userId == 0) {
276				return true;
277			}
278			
279			User user;
280			try {
281				user = userLocalService.getUser(userId);
282			} catch (PortalException e) {
283				throw new RuntimeException(e);
284			}
285			
286			Role roleCittadino;
287			try {
288				roleCittadino = RoleLocalServiceUtil.getRole(companyId, ROLE_CITTADINO);
289			} catch (PortalException e) {
290				throw new RuntimeException(e);
291			}
292			boolean isGestore = !user.getRoles().contains(roleCittadino);
293			return isGestore;
294		}
295	
296		private void hideBackOfficeName(ComunicazioneDto dto, long companyId, long scoupeGroupId) throws PortalException {
297			final Role roleCittadino = RoleLocalServiceUtil.getRole(companyId, ROLE_CITTADINO);
298			final Organization organization = organizationUtility.getSiteOrganization(scoupeGroupId);
299			dto.getMessaggi().forEach(messaggio->{
300				
301				User userMessaggio = null;
302				try {
303					userMessaggio = UserLocalServiceUtil.getUser(messaggio.getUserId());
304				} catch (PortalException e) {
305					userMessaggio = null;
306				}
307				
308				if((userMessaggio == null) || (userMessaggio!=null && !userMessaggio.getRoles().contains(roleCittadino))) {
309					messaggio.setUsername(organization.getName());
310				}
311			});
312		}
313	
314		private MessaggioDTO mapMessaggio(Messaggio messaggio) {
315			MessaggioDTO dto = new MessaggioDTO();
316			dto.setUsername(messaggio.getUserName());
317			dto.setContenuto(messaggio.getContenuto());
318			dto.setUserId(messaggio.getUserId());
319			dto.setData(messaggio.getCreateDate());
320			return dto;
321		}
322		
323	}
